          "Line 5: Declares variable: let text = 'The cat sat on the mat';",
          "Line 6: Logs output to console: console.log(text.replace('cat', 'dog'));",
          "Line 7: Declares variable: let phone = '123-456-7890';",
          "Line 8: Declares variable: let noHyphen = phone.replace(/-/g, '');",
          "Line 9: Logs output to console: console.log(noHyphen);",
          "Line 10: Declares variable: let name = 'John Doe';",
