          "Line 12: Logs output to console: console.log(initials);",
          "Line 13: Declares variable: let price = '$10.50';",
          "Line 14: Declares variable: let number = price.replace('$', '');",
          "Line 15: Logs output to console: console.log(number);",
          "Line 16: Declares variable: let msg = 'Hello %name%, welcome!';",
          "Line 17: Declares variable: let greeting = msg.replace('%name%', 'John');",
          "Line 18: Logs output to console: console.log(greeting);",
          "Line 19: Declares variable: let str2 = 'abc123def456';",
